package vn.cineman.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.cineman.dao.*;import vn.cineman.model.User8;import vn.cineman.service.*;import vn.cineman.util.Posters8;import java.io.*;import java.util.*;import java.time.*;import java.math.*;import java.net.*;
@MultipartConfig(maxFileSize=5242880,maxRequestSize=6291456)
@WebServlet("/app") public class AppServlet8 extends HttpServlet {
 private final CinemaService8 svc=new CinemaService8();
 private long number(HttpServletRequest r,String k){return Long.parseLong(r.getParameter(k));}
 private String value(HttpServletRequest r,String k){return Objects.toString(r.getParameter(k),"").trim();}
 private User8 user(HttpServletRequest r){return (User8)r.getSession().getAttribute("user");}
 private void redirect(HttpServletRequest r,HttpServletResponse s,String page)throws IOException{s.sendRedirect(r.getContextPath()+"/app?page="+page);}
 private LocalDate optionalDate(String value){if(value.isBlank())return null;try{return LocalDate.parse(value);}catch(DateTimeException e){throw new IllegalArgumentException("Ngày khởi chiếu không hợp lệ.");}}
 private String ageRating(String value){if(value.isBlank())return null;if(!Set.of("P","K","T13","T16","T18","C").contains(value))throw new IllegalArgumentException("Chọn phân loại độ tuổi hợp lệ.");return value;}
 private String trailerUrl(String value){if(value.isBlank())return null;if(value.length()>500)throw new IllegalArgumentException("URL trailer tối đa 500 ký tự.");try{URI uri=URI.create(value);if(!uri.isAbsolute()||!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();return uri.toASCIIString();}catch(IllegalArgumentException e){throw new IllegalArgumentException("URL trailer phải là địa chỉ HTTPS hợp lệ.");}}
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{
  String page=value(r,"page");if(page.isEmpty())page="movies";User8 u=user(r);if(u==null&&!Set.of("login","register","movies","detail").contains(page)){if(page.equals("booking"))r.getSession().setAttribute("afterLogin","booking&show="+number(r,"show"));if(page.equals("checkout"))r.getSession().setAttribute("afterLogin","checkout&id="+number(r,"id"));if(page.equals("receipt"))r.getSession().setAttribute("afterLogin","receipt&id="+number(r,"id"));redirect(r,s,"login");return;}
  if(r.getSession().getAttribute("csrf")==null)r.getSession().setAttribute("csrf",UUID.randomUUID().toString());
  try{if(Set.of("rooms","schedule","addMovie").contains(page))CinemaService8.allow(u,"MANAGER");if(Set.of("booking","checkout","orders","receipt").contains(page))CinemaService8.allow(u,"CUSTOMER");
   if(!Set.of("login","register","movies","rooms","schedule","booking","checkout","orders","receipt","detail","addMovie").contains(page)){s.sendError(404);return;}
   if(!Set.of("login","register").contains(page))try(var c=Db8.open()){
    switch(page){case "movies":var catalog=new CatalogDao8();int index=Math.max(1,Math.min(100000,Integer.parseInt(value(r,"p").isEmpty()?"1":value(r,"p"))));long genre=value(r,"genre").isEmpty()?0:number(r,"genre");var found=catalog.search(c,value(r,"q"),genre,index);r.setAttribute("hasNext",found.size()>12);r.setAttribute("index",index);r.setAttribute("movies",found.subList(0,Math.min(found.size(),12)));r.setAttribute("genres",catalog.genres(c));break;
    case "addMovie":r.setAttribute("genres",new CatalogDao8().genres(c));if(r.getSession().getAttribute("createKey")==null)r.getSession().setAttribute("createKey",UUID.randomUUID().toString());break;
    case "detail":long movieId=number(r,"id");var cat=new CatalogDao8();r.setAttribute("movie",cat.movie(c,movieId));r.setAttribute("genres",cat.movieGenres(c,movieId));r.setAttribute("shows",cat.shows(c,movieId));break;
    case "rooms":r.setAttribute("rooms",svc.dao.rooms(c));break;
    case "schedule":r.setAttribute("movies",svc.dao.movies(c,""));r.setAttribute("rooms",svc.dao.rooms(c));r.setAttribute("shows",svc.dao.shows(c));break;
    case "booking":long id=number(r,"show");new CheckoutDao8().expireAll(c);var show=svc.dao.show(c,id);if(show==null)throw new IllegalArgumentException("Không tìm thấy suất chiếu.");r.setAttribute("show",show);r.setAttribute("movie",new CatalogDao8().movie(c,((Number)show.get("movie_id")).longValue()));r.setAttribute("seats",svc.dao.seats(c,id));r.setAttribute("requestKey",UUID.randomUUID().toString());var buyer=svc.dao.customerContact(c,u.id());if(buyer==null)throw new SecurityException();Object phoneDraft=r.getSession().getAttribute("contactPhoneDraft");if(phoneDraft!=null){buyer.put("phone",phoneDraft);r.getSession().removeAttribute("contactPhoneDraft");}r.setAttribute("buyer",buyer);break;
    case "checkout":long orderId=number(r,"id");new CheckoutDao8().expireAll(c);var checkoutOrder=svc.dao.receipt(c,orderId);if(checkoutOrder==null||checkoutOrder.get("show_id")==null)throw new IllegalArgumentException("Không tìm thấy đơn đặt vé.");if(((Number)checkoutOrder.get("actor_id")).longValue()!=u.id())throw new SecurityException();long showId=((Number)checkoutOrder.get("show_id")).longValue();var checkoutDao=new CheckoutDao8();checkoutDao.expire(c,showId);checkoutOrder=checkoutDao.order(c,orderId);r.setAttribute("order",checkoutOrder);r.setAttribute("checkoutSeats",checkoutDao.seatSummary(c,orderId));if(checkoutOrder.get("expires_at") instanceof LocalDateTime expiry)r.setAttribute("secondsLeft",Math.max(0,Duration.between(LocalDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh")),expiry).getSeconds()));break;
    case "orders":new CheckoutDao8().expireAll(c);boolean staff="MANAGER".equals(u.role());var ordersList=svc.dao.orders(c,u.id(),staff);LocalDateTime nowOrders=LocalDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh"));for(var o:ordersList){if("PENDING".equals(o.get("status"))&&o.get("expires_at") instanceof LocalDateTime exp){long sec=Duration.between(nowOrders,exp).getSeconds();if(sec>0){o.put("secondsLeft",sec);}else{o.put("status","EXPIRED");o.put("secondsLeft",0L);}}}r.setAttribute("orders",ordersList);break;
    case "receipt":new CheckoutDao8().expireAll(c);var order=svc.dao.receipt(c,number(r,"id"));if(order==null)throw new IllegalArgumentException("Không tìm thấy hóa đơn.");if(u.role().equals("CUSTOMER")&&((Number)order.get("actor_id")).longValue()!=u.id())throw new SecurityException();var tickets=svc.dao.tickets(c,number(r,"id"));if(tickets.isEmpty()){r.setAttribute("pendingSeats",new CheckoutDao8().seatSummary(c,number(r,"id")));}if("PENDING".equals(order.get("status"))&&order.get("expires_at") instanceof LocalDateTime expiry){long sec=Duration.between(LocalDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh")),expiry).getSeconds();if(sec>0){r.setAttribute("secondsLeft",sec);}else{order.put("status","EXPIRED");r.setAttribute("secondsLeft",0L);}}r.setAttribute("order",order);r.setAttribute("tickets",tickets);break;
    }}
  }catch(SecurityException e){s.sendError(403);return;}catch(Exception e){r.setAttribute("error",friendly(e));}
  r.setAttribute("page",page);r.getRequestDispatcher("/WEB-INF/views/app.jsp").forward(r,s);
 }
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{
  r.setCharacterEncoding("UTF-8");if(!Objects.equals(r.getSession().getAttribute("csrf"),r.getParameter("csrf"))||r.getParameter("csrf")==null){s.sendError(403);return;}
  String action=value(r,"action"),next="movies";User8 u=user(r);
  try{if(u==null&&!Set.of("login","register").contains(action))throw new SecurityException();
   switch(action){case "login":u=svc.login(value(r,"email").toLowerCase(Locale.ROOT),r.getParameter("password"));r.changeSessionId();r.getSession().setAttribute("user",u);r.getSession().setAttribute("csrf",UUID.randomUUID().toString());if(r.getSession().getAttribute("afterLogin")!=null){next=(String)r.getSession().getAttribute("afterLogin");r.getSession().removeAttribute("afterLogin");}break;
    case "register":svc.register(value(r,"name"),value(r,"email"),r.getParameter("password"));next="login";break;
    case "logout":r.getSession().invalidate();redirect(r,s,"login");return;
    case "movie":svc.saveMovie(u,number(r,"id"),value(r,"title"),value(r,"genre"),(int)number(r,"duration"),value(r,"description"));break;
    case "room":next="rooms";svc.saveRoom(u,number(r,"id"),value(r,"name"),(int)number(r,"rows"),(int)number(r,"cols"));break;
    case "deleteMovie":svc.delete(u,"movie",number(r,"id"));break;
    case "deleteRoom":next="rooms";svc.delete(u,"room",number(r,"id"));break;
    case "schedule":next="schedule";svc.schedule(u,number(r,"movie"),number(r,"room"),LocalDateTime.parse(value(r,"start")),new BigDecimal(value(r,"price")));break;
    case "createMovie":next="addMovie";CinemaService8.allow(u,"MANAGER");String title=CinemaService8.required(value(r,"title"),150),description=CinemaService8.required(value(r,"description"),5000);int duration=Integer.parseInt(value(r,"duration"));if(duration<1||duration>600)throw new IllegalArgumentException("Thời lượng phải từ 1 đến 600 phút.");LocalDate releaseDate=optionalDate(value(r,"releaseDate"));String rating=ageRating(value(r,"ageRating")),trailer=trailerUrl(value(r,"trailerUrl"));String[] selected=r.getParameterValues("genres");if(selected==null||selected.length==0)throw new IllegalArgumentException("Chọn ít nhất một thể loại.");var genres=Arrays.stream(selected).map(Long::parseLong).distinct().toList();String createKey=value(r,"createKey");if(!Objects.equals(createKey,r.getSession().getAttribute("createKey")))throw new IllegalArgumentException("Biểu mẫu hết hạn. Vui lòng tải lại.");Posters8.Upload8 upload=Posters8.save(r.getPart("poster"));try{long created=svc.transaction(c->new CatalogDao8().create(c,title,duration,description,genres,createKey,upload.key(),upload.mime(),upload.size(),releaseDate,rating,trailer));next="detail&id="+created;r.getSession().removeAttribute("createKey");r.getSession().removeAttribute("movieDraft");try(var check=Db8.open()){if(!upload.key().equals(new CatalogDao8().movie(check,created).get("poster_key")))Posters8.remove(upload);}}catch(Exception e){Posters8.remove(upload);throw e;}break;
    case "buy":next="booking&show="+number(r,"show");String[] raw=r.getParameterValues("seat");List<Long> seats=raw==null?List.of():Arrays.stream(raw).map(Long::parseLong).toList();long orderId=new CheckoutService8().begin(u,number(r,"show"),seats,value(r,"card"),value(r,"contactPhone"),value(r,"requestKey"));r.getSession().removeAttribute("contactPhoneDraft");next="checkout&id="+orderId;break;
    case "completeDemoPayment":next="receipt&id="+number(r,"id");new CheckoutService8().completeDemo(u,number(r,"id"));break;
    case "failDemoPayment":next="receipt&id="+number(r,"id");new CheckoutService8().failDemo(u,number(r,"id"));break;
    default:throw new IllegalArgumentException("Thao tác không hợp lệ.");}
   r.getSession().setAttribute("flash","Thao tác thành công.");
  }catch(SecurityException e){s.sendError(403);return;}catch(Exception e){r.getSession().setAttribute("error",friendly(e));if(action.equals("buy"))r.getSession().setAttribute("contactPhoneDraft",value(r,"contactPhone"));if(action.equals("createMovie")){r.getSession().setAttribute("movieDraft",Map.of("title",value(r,"title"),"description",value(r,"description"),"duration",value(r,"duration"),"releaseDate",value(r,"releaseDate"),"ageRating",value(r,"ageRating"),"trailerUrl",value(r,"trailerUrl"),"genres",Arrays.asList(r.getParameterValues("genres")==null?new String[0]:r.getParameterValues("genres"))));}if(action.equals("login")||action.equals("register"))next=action;}
  redirect(r,s,next);
 }
 private String friendly(Exception e){if(e instanceof IllegalArgumentException)return e instanceof NumberFormatException?"Vui lòng nhập số hợp lệ.":e.getMessage();if(e instanceof java.sql.SQLIntegrityConstraintViolationException)return "Dữ liệu trùng hoặc đã được sử dụng. Vui lòng kiểm tra lại.";String ref=UUID.randomUUID().toString().substring(0,8);getServletContext().log("CineMan error "+ref,e);if(e instanceof java.sql.SQLException sql && sql.getSQLState()!=null && sql.getSQLState().startsWith("08"))return "Không kết nối được CSDL. Mã hỗ trợ: "+ref;return "Hệ thống không xử lý được yêu cầu. Mã hỗ trợ: "+ref;}
}
